// used by the replan solver to also respect a not-yet-applied proposal)
// overlaps `tableIds` during [startsAtMs, endsAtMs).
function isClosed(restaurant, tableIds, startsAtMs, endsAtMs, extraClosures) {
  const closures = extraClosures ? restaurant.closures.concat(extraClosures) : restaurant.closures;
  const wanted = new Set(tableIds);
  for (const c of closures) {
    if (!wanted.has(c.table_id)) continue;
    if (intervalsOverlap(startsAtMs, endsAtMs, c.from_ms, c.to_ms)) return true;
  }
  return false;
}

// Combines the "taken by another reservation" and "table is closed"
// checks: both produce the same 409 table_unavailable outcome.
function isUnavailable(state, restaurant, tableIds, startsAtMs, endsAtMs, excludeIds) {
  return hasOverlap(state, tableIds, startsAtMs, endsAtMs, excludeIds)
    || isClosed(restaurant, tableIds, startsAtMs, endsAtMs);
}

